window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-17591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔπωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6352 na letra ε · nº geral 17591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abundante em potros ou cavalos. 〈εὖ, πῶλος〉</p></section></article>\n<article id=\"entry-dgp-17592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρακύλων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6353 na letra ε · nº geral 17592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Εὐροκλύδων.</p></section></article>\n<article id=\"entry-dgp-17593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑράμην</h1><div class=\"entry-meta\"><span>DGP · ordem 6354 na letra ε · nº geral 17593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐράξ</h1><div class=\"entry-meta\"><span>DGP · ordem 6355 na letra ε · nº geral 17594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. no sentido da largura; transversalmente; de lado. 〈εὐρύς〉</p></section></article>\n<article id=\"entry-dgp-17595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρέα</h1><div class=\"entry-meta\"><span>DGP · ordem 6356 na letra ε · nº geral 17595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. fem. jôn. ou ac. masc. sing. poét. ou pl. n. de εὐρύς.</p></section></article>\n<article id=\"entry-dgp-17596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρεής</h1><div class=\"entry-meta\"><span>DGP · ordem 6357 na letra ε · nº geral 17596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εὐρεῖος = εὔροος.</p></section></article>\n<article id=\"entry-dgp-17597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρέθην</h1><div class=\"entry-meta\"><span>DGP · ordem 6358 na letra ε · nº geral 17597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρεῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 6359 na letra ε · nº geral 17598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de εὐρύς.</p></section></article>\n<article id=\"entry-dgp-17599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 6360 na letra ε · nº geral 17599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρεμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6361 na letra ε · nº geral 17600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὕρημα.</p></section></article>\n<article id=\"entry-dgp-17601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρέμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 6362 na letra ε · nº geral 17601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 ép. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρεσιλογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6363 na letra ε · nº geral 17602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criar argumentos; cogitar justificativas.</p></section></article>\n<article id=\"entry-dgp-17603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρεσιλογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6364 na letra ε · nº geral 17603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 habilidade para construir argumentos 2 facilidade de expressão. 〈εὑρίσκω, λόγος〉</p></section></article>\n<article id=\"entry-dgp-17604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6365 na letra ε · nº geral 17604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invenção; descoberta. 〈εὑρίσκω〉</p></section></article>\n<article id=\"entry-dgp-17605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρετέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6366 na letra ε · nº geral 17605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρετής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6367 na letra ε · nº geral 17606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inventor. 〈εὑρίσκω〉</p></section></article>\n<article id=\"entry-dgp-17607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6368 na letra ε · nº geral 17607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inventivo. 〈εὑρετός〉</p></section></article>\n<article id=\"entry-dgp-17608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρετός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6369 na letra ε · nº geral 17608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρηκα</h1><div class=\"entry-meta\"><span>DGP · ordem 6370 na letra ε · nº geral 17609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª sing. perf. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6371 na letra ε · nº geral 17610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 invenção; descoberta 2 descoberta imprevista; achado 3 expediente; remédio contra, gen. 〈εὑρίσκω〉</p></section></article>\n<article id=\"entry-dgp-17611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 6372 na letra ε · nº geral 17611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. subj. aor.2 ép. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρησιλογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6373 na letra ε · nº geral 17612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὑρεσιλογία.</p></section></article>\n<article id=\"entry-dgp-17613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 6374 na letra ε · nº geral 17613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª sing. fut. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6375 na letra ε · nº geral 17614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bom ou fácil de dizer. 〈εὖ, ῥητός〉</p></section></article>\n<article id=\"entry-dgp-17615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6376 na letra ε · nº geral 17615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὔρις.</p></section></article>\n<article id=\"entry-dgp-17616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐριπίδειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6377 na letra ε · nº geral 17616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Eurípides. 〈Εὐριπίδης〉</p></section></article>\n<article id=\"entry-dgp-17617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐριπίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6378 na letra ε · nº geral 17617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eurípides, poeta trágico. 〈Εὔριπος〉</p></section></article>\n<article id=\"entry-dgp-17618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὔριπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6379 na letra ε · nº geral 17618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Euripo, atual Egribo, estreito entre a Eubéia e a Beócia, famoso pela agitação de suas águas 2 braço de mar estreito. 〈εὖ, ῥιπή〉</p></section></article>\n<article id=\"entry-dgp-17619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρις, ινος</h1><div class=\"entry-meta\"><span>DGP · ordem 6380 na letra ε · nº geral 17619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que tem bom nariz; de bom faro. 〈εὖ, ῥίς〉</p></section></article>\n<article id=\"entry-dgp-17620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρίσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 6381 na letra ε · nº geral 17620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ηὕρισχον, fut. εὑρήσω, aor.2 ηὗρον, perf. ηὕρηχα; pas. fut. εὑρεθήσομαι, aor. ηὑρέθην, perf. ηὕρημαι; méd. fut. εὑρήσομαι, aor.2 εὑρόμην, aor.1 εὑράμην e ηὑράμην, perf. εὕρημαι) ativa 1 encontrar; achar casualmente ou após busca 2 descobrir; imaginar; inventar 3 encontrar o meio ou o modo de; ser capaz de, inf. ou or. conj. (ὅπως, ὥστε) 4 encontrar após reflexão; reconhecer, ac.; achar que, or. part. ou inf. 5 encontrar; conquistar; ganhar; obter 6 (mercadoria) ter preço ou valor 7 obter de; receber; encontrar da parte de, πρός e gen. média 8 achar; encontrar; descobrir; 9 proporcionar para si; obter para si 1 εὗρεν δ᾽ εὐρύοπα Κρονίδην ἄτερ ἥμενον ἄλλων hom. encontrou o Cronida de voz possante sentado longe dos outros 2 ἐξ ἀμηχάνων πόρον εὑρ. ésql. descobrir uma saída para as dificuldades, εὑρ. μηχανὴν σωτηρίας ésql. encontrar um meio de salvação, εὑρ. ὀχήματα λινόπτερα ésql. inventar veículos com asas de linho 3 οὐδέ τι τέκμωρ εὑρέμεναι δύνασαι hom. não és capaz de descobrir nenhuma saída, εὗρεν ἐμφῦναι τοῖς Μακεδόνων πράγμασιν plut. encontrou o meio de inserir-se nas questões dos macedônios, οἱ οὐδ᾽ ὅπως καθεζομένους χρὴ τὸ βέλος ἀφεῖναι εὑρήσουσι tuc. não descobrirão como devem, sentados, lançar os dardos 4 τἄλλα δ᾽ εὑρήσεις ὑπουργεῖν ὄντας ἡμᾶς οὐ κακούς ar. quanto ao resto, não nos encontrarás indispostos a vos servir, εὕρισκε Λακεδαιμονίους προέχοντας her. reconheceu que os lacedemônios tinham vantagem, εὕρισκε πρῆγμά οἱ εἶναι achou que lhe competia... 5 τὰ χρήματ᾽ ἀνθρώποισιν εὑρίσκει φίλους sóf. a riqueza conquista amigos para os homens, εὑρ. ἀρετάν pínd. atingir a virtude, εὑρεῖν πολλὸν χρυσίον her. obter uma grande soma de ouro, i.e., bom preço (por um objeto vendido), ἀποδίδοσθαι τοῦ εὑρόντος xen. vender pelo preço que encontra, i. e., a qualquer preço 6 οἰκία εὑρίσκουσα δισχιλίας [δραχμάς] is. casa que vale vinte mil dracmas 7 δεινὰ δ᾽ εὑροῦσαν πρὸς αὐθαίμων πάθη sóf. recebeu tratamento cruel dos consangüíneos 8 τὰ δ᾽ ἔργα τοὺς λόγους εὑρίσκεται sóf. lit. as ações por si mesmas descobrem os nomes (que a elas correspondem) 9 εὑρ. κλέος pínd. obter glória, εὑρ. κακόν hom. proporcionar para si um mal, i.e., causar mal a si próprio.</p></section></article>\n<article id=\"entry-dgp-17621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐροέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6382 na letra ε · nº geral 17621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter curso próspero; ser favorável 2 (pessoa) prosperar; ser feliz 3 ter a palavra fluente; falar com fluência. 〈εὔροος〉</p></section></article>\n<article id=\"entry-dgp-17622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔροια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6383 na letra ε · nº geral 17622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curso fácil ou abundante; curso livre 2 abundância do estilo ou da palavra; eloqüência 3 feliz curso dos acontecimentos; prosperidade; êxito. 〈εὔροος〉</p></section></article>\n<article id=\"entry-dgp-17623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐροκλύδων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6384 na letra ε · nº geral 17623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Euróclido, vento tempestuoso do nordeste.</p></section></article>\n<article id=\"entry-dgp-17624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρόμην, εὗρον</h1><div class=\"entry-meta\"><span>DGP · ordem 6385 na letra ε · nº geral 17624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔροος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 6386 na letra ε · nº geral 17625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de curso fácil ou abundante 2 fluente (estilo) 3 de curso favorável; próspero; propício (fato). 〈εὖ, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-17626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖρος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6387 na letra ε · nº geral 17626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">largura. 〈εὐρύς〉</p></section></article>\n<article id=\"entry-dgp-17627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὖρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6388 na letra ε · nº geral 17627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Euro, vento do sudoeste.</p></section></article>\n<article id=\"entry-dgp-17628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρους</h1><div class=\"entry-meta\"><span>DGP · ordem 6389 na letra ε · nº geral 17628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de εὔροος.</p></section></article>\n<article id=\"entry-dgp-17629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋρραφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6390 na letra ε · nº geral 17629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem cosido; bem ligado. 〈εὖ, ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-17630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋρρεής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6391 na letra ε · nº geral 17630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὐρεής.</p></section></article>\n<article id=\"entry-dgp-17631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋρρεῖος</h1><div class=\"entry-meta\"><span>DGP · ordem 6392 na letra ε · nº geral 17631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐρρεέος gen. de ἐϋρρεής.</p></section></article>\n<article id=\"entry-dgp-17632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋρρείτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 6393 na letra ε · nº geral 17632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὔροος.</p></section></article>\n<article id=\"entry-dgp-17633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐΰρροος, οος, οον</h1><div class=\"entry-meta\"><span>DGP · ordem 6394 na letra ε · nº geral 17633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὔροος.</p></section></article>\n<article id=\"entry-dgp-17634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυάγυια, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 6395 na letra ε · nº geral 17634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de largas ruas: εὐρ. δίκα plut. julgamento em plena rua, i.e., julgamento público. 〈εὐρύς, ἀγυιά〉</p></section></article>\n<article id=\"entry-dgp-17635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρυδίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6396 na letra ε · nº geral 17635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eurídice, n. da mulher de Orfeu, e da mulher de Creonte, rei de Tebas. 〈εὐρύς, δίκη〉</p></section></article>\n<article id=\"entry-dgp-17636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυθμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6397 na letra ε · nº geral 17636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 movimento bem ritmado; cadência; harmonia 2 proporção harmoniosa; graça 3 Medic. habilidade da mão (de cirurgião). 〈εὔρυθμος〉</p></section></article>\n<article id=\"entry-dgp-17637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρυθμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6398 na letra ε · nº geral 17637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem ritmado; bem cadenciado 2 bem proporcionado; harmonioso 3 gracioso. 〈εὖ, ῥυθμός〉</p></section></article>\n<article id=\"entry-dgp-17638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύθμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6399 na letra ε · nº geral 17638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de forma bem ritmada; com boa cadência 2 com harmonia; com graça 3 Medic. com habilidade; com delicadeza.</p></section></article>\n<article id=\"entry-dgp-17639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρύκλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6400 na letra ε · nº geral 17639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Euricléia, ama de Odisseu. 〈εὐρύς, κλέος〉</p></section></article>\n<article id=\"entry-dgp-17640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυκρείων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 6401 na letra ε · nº geral 17640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de amplos poderes; que possui vastos domínios. 〈εὐρύς, κρείων〉</p></section></article>\n<article id=\"entry-dgp-17641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυμέδων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 6402 na letra ε · nº geral 17641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que reina longe; que reina sobre povos distantes. 〈εὐρύς, μέδω〉</p></section></article>\n<article id=\"entry-dgp-17642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυμέτωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6403 na letra ε · nº geral 17642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de larga fronte. 〈εὐρύς, μέτωπον〉</p></section></article>\n<article id=\"entry-dgp-17643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 6404 na letra ε · nº geral 17643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ηὔρυνον, fut. εὐρυνῶ, aor. ηὔρυνα, poét. εὔρυνα, perf. desus.) 1 ampliar; aumentar 2 fazer esvaziar; tornar deserto: εὐρ. ἀγῶνα hom. preparar (aplainando-o ou esvaziando-o) um terreno (para a dança), τὸ μέσον εὐρ. her. deixar um espaço largo no centro. 〈εὐρύς〉</p></section></article>\n<article id=\"entry-dgp-17644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύνωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6405 na letra ε · nº geral 17644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de costas largas. 〈εὐρύς, νῶτος〉</p></section></article>\n<article id=\"entry-dgp-17645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυοδείη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 6406 na letra ε · nº geral 17645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) jôn. de largos caminhos; vasta; espaçosa, epít. da Terra. 〈εὐρύς, ὁδός〉</p></section></article>\n<article id=\"entry-dgp-17646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύοπα1</h1><div class=\"entry-meta\"><span>DGP · ordem 6407 na letra ε · nº geral 17646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. voc. ou ac. ép. de voz que ressoa longe; de voz possante (Zeus). 〈εὐρύς, ὄψ〉</p></section></article>\n<article id=\"entry-dgp-17647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύοπα2</h1><div class=\"entry-meta\"><span>DGP · ordem 6408 na letra ε · nº geral 17647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. voc. ou ac. ép. que enxerga longe (sol). 〈εὐρύς, ὄψομαι〉</p></section></article>\n<article id=\"entry-dgp-17648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6409 na letra ε · nº geral 17648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de larga passagem; de inúmeros caminhos; vasto; imenso. 〈εὐρύς, πόρος〉</p></section></article>\n<article id=\"entry-dgp-17649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυπυλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6410 na letra ε · nº geral 17649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de largas portas. 〈εὐρύς, πύλη〉</p></section></article>\n<article id=\"entry-dgp-17650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυρέεθρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6411 na letra ε · nº geral 17650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de larga corrente. 〈εὐρύς, ῥέεθρον〉</p></section></article>\n<article id=\"entry-dgp-17651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυρέων, έουσα, έον</h1><div class=\"entry-meta\"><span>DGP · ordem 6412 na letra ε · nº geral 17651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de larga corrente. 〈εὐρὺς, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-17652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύς, εὐρεῖα, εὐρύ</h1><div class=\"entry-meta\"><span>DGP · ordem 6413 na letra ε · nº geral 17652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 largo 2 que se estende ao longe; vasto; espaçoso 3 extensão (glória).</p></section></article>\n<article id=\"entry-dgp-17653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυσθενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6414 na letra ε · nº geral 17653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cuja força atinge longe; poderoso à distância; forte; possante. 〈εὐρύς, σθένος〉</p></section></article>\n<article id=\"entry-dgp-17654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ευρύστερνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6415 na letra ε · nº geral 17654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de peito largo; de amplo seio. 〈εὐρύς, στέρνον〉</p></section></article>\n<article id=\"entry-dgp-17655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρύτειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6416 na letra ε · nº geral 17655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Êurito: Εὐρυτεία πόλις sóf. a cidade de Êurito, a Ecália, Εὐρυτεία παρθένος sóf. a filha de Êurito, Iole. 〈Εὔρυτος〉</p></section></article>\n<article id=\"entry-dgp-17656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρυτίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6417 na letra ε · nº geral 17656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">descendente de Êurito, epít. de Ífito. 〈Εὔρυτος〉</p></section></article>\n<article id=\"entry-dgp-17657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6418 na letra ε · nº geral 17657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de águas agradáveis ou abundantes ♦ ὁ Εὔρυτος 2 Êurito, rei da Ecália, pai de Iole. 〈εὖ, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-17658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυφυής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6419 na letra ε · nº geral 17658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cresce ou se desenvolve vastamente. 〈εὐρύς, φύω〉</p></section></article>\n<article id=\"entry-dgp-17659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυχαδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6420 na letra ε · nº geral 17659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de grande capacidade; grande (taça). 〈εὐρύς, χανδάνω〉</p></section></article>\n<article id=\"entry-dgp-17660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύχορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6421 na letra ε · nº geral 17660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de amplo espaço; largo; espaçoso. 〈εὐρύς, χώρα〉</p></section></article>\n<article id=\"entry-dgp-17661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυχωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6422 na letra ε · nº geral 17661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espaço amplo; espaço aberto 2 espaço aberto e livre (para um combate) 3 campo livre, i.e., liberdade ou facilidade para fazer algo. 〈εὐρύς, χώρα〉</p></section></article>\n<article id=\"entry-dgp-17662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρω</h1><div class=\"entry-meta\"><span>DGP · ordem 6423 na letra ε · nº geral 17662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 at. de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 6424 na letra ε · nº geral 17663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de largas ruas. 〈εὐρύς, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-17664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρώεις, ώεσσα, ῶεν</h1><div class=\"entry-meta\"><span>DGP · ordem 6425 na letra ε · nº geral 17664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bolorento; úmido. 〈εὐρώς〉</p></section></article>\n<article id=\"entry-dgp-17665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρών</h1><div class=\"entry-meta\"><span>DGP · ordem 6426 na letra ε · nº geral 17665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de εὑρίσκω.</p></section></article>\n<article id=\"entry-dgp-17666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρωπαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6427 na letra ε · nº geral 17666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Europa. 〈Εὐρώπη〉</p></section></article>\n<article id=\"entry-dgp-17667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρωπεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 6428 na letra ε · nº geral 17667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de Europo. 〈Εὐρωπός〉</p></section></article>\n<article id=\"entry-dgp-17668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρώπη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6429 na letra ε · nº geral 17668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Europa, mãe de Minos 2 a Europa. 〈εὐρύς, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-17669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρωπήϊος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6430 na letra ε · nº geral 17669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Εὐρωπαῖος.</p></section></article>\n<article id=\"entry-dgp-17670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρωπός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6431 na letra ε · nº geral 17670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">largo; vasto; espaçoso. 〈εὐρύς, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-17671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρωπός</h1><div class=\"entry-meta\"><span>DGP · ordem 6432 na letra ε · nº geral 17671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Εὔρωπος, ου (ἡ) Europo, n. de cidade da Macedônia e da Síria.</p></section></article>\n<article id=\"entry-dgp-17672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρώς, ῶτος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6433 na letra ε · nº geral 17672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bolor; sujeira; podridão causada pela umidade 2 umidade.</p></section></article>\n<article id=\"entry-dgp-17673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρωστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6434 na letra ε · nº geral 17673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">força; vigor. 〈εὔρωστος〉</p></section></article>\n<article id=\"entry-dgp-17674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔρωστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6435 na letra ε · nº geral 17674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forte; robusto; vigoroso. 〈εὖ, ῥώννυμι〉</p></section></article>\n<article id=\"entry-dgp-17675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρώστως</h1><div class=\"entry-meta\"><span>DGP · ordem 6436 na letra ε · nº geral 17675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com vigor; com força.</p></section></article>\n<article id=\"entry-dgp-17676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐρώτας, α (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6437 na letra ε · nº geral 17676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. Eurota, rio da Lacônia que banha a planície de Esparta.</p></section></article>\n<article id=\"entry-dgp-17677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρωτιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6438 na letra ε · nº geral 17677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar-se bolorento; embolorar 2 estar embolorado, estragado, sujo. 〈εὐρώς〉</p></section></article>\n<article id=\"entry-dgp-17678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐΰς,</h1><div class=\"entry-meta\"><span>DGP · ordem 6439 na letra ε · nº geral 17678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ép. ἠΰς (masc.) e ἠΰ (n.), gen. ép. ἑῆος, ac. masc. ἐΰν e n. ἠΰ 1 bom; valente; corajoso; nobre ♦ τῶν ἐάων ou ἑάων 2 bens; riquezas.</p></section></article>\n<article id=\"entry-dgp-17679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὗσα</h1><div class=\"entry-meta\"><span>DGP · ordem 6440 na letra ε · nº geral 17679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εὖσα aor. de εὕω ou εὔω.</p></section></article>\n<article id=\"entry-dgp-17680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσαρκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6441 na letra ε · nº geral 17680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de boas condições; bem nutrido; carnudo; gordo. 〈εὖ, σάρξ〉</p></section></article>\n<article id=\"entry-dgp-17681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσέβεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6442 na letra ε · nº geral 17681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 respeito e amor aos deuses; piedade 2 piedade; veneração; respeito filial por alguém, gen. ou εἰς, πρός ou περί e ac. 3 reputação de piedade filial 4 pl. atos de piedade 5 tard. temor de Deus.</p></section></article>\n<article id=\"entry-dgp-17682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6443 na letra ε · nº geral 17682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 demonstrar piedade (religiosa ou filial); ser piedoso, respeitoso com, εἰς, πρός ou περί e ac. 2 ser religioso 3 respeitar; venerar. 〈εὐσεβής〉</p></section></article>\n<article id=\"entry-dgp-17683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6444 na letra ε · nº geral 17683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 piedoso 2 que age piamente ou observa os deveres (com os deuses ou pais) com, πρός, εἰς ou περί e ac. 3 inocente 4 legítimo (filho) 5 sagrado; conforme os deveres (morais, religiosos) ♦ τὸ εὐσεβές 6 piedade; respeito. 〈εὖ, σέβομαι〉</p></section></article>\n<article id=\"entry-dgp-17684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6445 na letra ε · nº geral 17684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐσέβεια.</p></section></article>\n<article id=\"entry-dgp-17685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6446 na letra ε · nº geral 17685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. piedosamente; de forma piedosa; com piedade (religiosa filial).</p></section></article>\n<article id=\"entry-dgp-17686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσελμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6447 na letra ε · nº geral 17686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">munido de bom convés, de boas pranchas, de bancos firmes. 〈εὖ, σέλμα〉</p></section></article>\n<article id=\"entry-dgp-17687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσεπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6448 na letra ε · nº geral 17687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de respeito; reverente; santo (pureza). 〈εὖ, σέβομαι〉</p></section></article>\n<article id=\"entry-dgp-17688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6449 na letra ε · nº geral 17688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é bom sinal; de bom augúrio 2 que oferece sinal seguro, evidente: καπνῷ δ᾽ ἁλοῦσα εὔ­σημος πόλις ésql. a fumaça é sinal seguro de que a cidade foi tomada 3 fácil de reconhecer; distinto (grito). 〈εὖ, σῆμα〉</p></section></article>\n<article id=\"entry-dgp-17689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσήμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6450 na letra ε · nº geral 17689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo claro ou evidente.</p></section></article>\n<article id=\"entry-dgp-17690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσηπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6451 na letra ε · nº geral 17690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que apodrece com facilidade. 〈εὖ, σήπω〉</p></section></article>\n";
